/**
 * The generated spec index: `.ai/specs/README.md`, from the metadata table in each spec.
 *
 * ```
 * pnpm generate-spec-index
 * ```
 *
 * ## Why generated
 *
 * The prior art this convention is taken from keeps its index by hand, and it is 42 KB of it -
 * every row a chance for the index and the tree to disagree, and no way to tell which is right. A
 * generated file has one source (the documents themselves) and this repository already runs that
 * pattern twice, for the route tree and for `drizzle/`: regenerate, never edit, and let
 * `git diff --exit-code` in `.ai/scripts/check-generated.sh` be what notices.
 *
 * Output is written through the repository's own Prettier so the file is formatted the way every
 * other document is, rather than earning a `.prettierignore` entry and drifting out of `pnpm check`
 * with it.
 *
 * Assertions are not this module's job: {@link auditSpecs} carries them and
 * `__tests__/spec-registry.test.ts` fails on them. An index that refused to render a tree with a
 * typo in it would leave the reader with nothing at the moment they most need the list.
 */
import { writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { pathToFileURL } from 'node:url'

import { format, resolveConfig } from 'prettier'

import { SPEC_ROOT, auditSpecs } from './registry.ts'
import type { Spec, SpecStatus } from './registry.ts'

const INDEX = join(SPEC_ROOT, 'README.md')

/**
 * The repository the `#n` references point at.
 *
 * Hard-coded rather than read from the git remote: a generated file that changes with whoever's
 * clone ran the generator fails the gate's `git diff --exit-code` on a fork for a reason that has
 * nothing to do with the change under review.
 */
const REPOSITORY = 'https://github.com/design4pro/planned.travel'

/** Lifecycle order, which is also reading order: what is being decided, then built, then done. */
const SECTIONS: ReadonlyArray<{ status: SpecStatus; heading: string }> = [
  { status: 'draft', heading: 'Draft — being written' },
  { status: 'ready', heading: 'Ready — merged, waiting for a build' },
  { status: 'in-progress', heading: 'In progress — a build is open' },
  { status: 'implemented', heading: 'Implemented' },
  { status: 'archived', heading: 'Archived — superseded or abandoned' },
]

/**
 * `/issues/n` rather than `/pull/n`, for every reference in the index.
 *
 * GitHub redirects between the two for the same number, so one form is enough and the generator
 * does not have to know which of the two a reference is - which it cannot, from the document.
 */
const reference = (id: number): string => `[#${id}](${REPOSITORY}/issues/${id})`

const list = (ids: ReadonlyArray<number>): string =>
  ids.length === 0 ? '—' : ids.map(reference).join(', ')

/**
 * A cell's own `|` escaped, so a title carrying one cannot add a column.
 *
 * Nothing constrains the `H1` a spec is written with, and GFM discards the cells past the header
 * count: one `# Trips | places` would silently drop the last column from that row, and neither
 * Prettier nor the staleness gate would notice - both only ever compare the generator to itself.
 */
const cell = (text: string): string => text.replaceAll('|', '\\|')

const row = (spec: Spec): string => {
  const href = spec.path.slice(SPEC_ROOT.length + 1)
  const cells = [
    `[${cell(spec.title)}](${href})`,
    spec.date,
    spec.issue === null ? '—' : reference(spec.issue),
    spec.specPr === null ? '—' : reference(spec.specPr),
    list(spec.status === 'archived' ? spec.supersededBy : spec.implementation),
  ]
  return `| ${cells.join(' | ')} |`
}

export const renderIndex = (specs: ReadonlyArray<Spec>): string => {
  const lines = [
    '# Specifications',
    '',
    '<!-- Generated by `pnpm generate-spec-index`. Edit the metadata table in the spec, not this file. -->',
    '',
    'One document per designed change. The directory a spec sits in is its state, the table under',
    'its `H1` names the issue and the pull requests behind it, and both are held together by',
    '`scripts/specs/__tests__/spec-registry.test.ts`. The rules are in [AGENTS.md](AGENTS.md).',
    '',
  ]

  for (const { status, heading } of SECTIONS) {
    const section = specs.filter((spec) => spec.status === status)
    if (section.length === 0) continue

    // An archived spec has no implementation and would show a column of dashes; what the reader
    // wants in its place is what replaced it.
    const last = status === 'archived' ? 'Superseded by' : 'Implementation'

    lines.push(
      `## ${heading} (${section.length})`,
      '',
      `| Spec | Date | Issue | Spec PR | ${last} |`,
      '| --- | --- | --- | --- | --- |',
      ...section.map(row),
      '',
    )
  }

  return lines.join('\n')
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  const { specs } = auditSpecs()
  const options = await resolveConfig(INDEX)
  writeFileSync(
    INDEX,
    await format(renderIndex(specs), { ...options, filepath: INDEX }),
  )
  console.log(`${INDEX}: ${specs.length} specs`)
}
